const body = $json.body ?? $json;
const text = (value) => String(value ?? '').trim();
const candidate = body.candidate ?? {};
const email = text(candidate.email).toLowerCase();
const link = text(body.applicationLink);
if (body.eventType !== 'application_invite_email_requested') throw new Error('Invalid application invite email event.');
if (!email || !email.includes('@')) throw new Error('Candidate email is missing.');
if (!link || !/^https?:\/\//i.test(link)) throw new Error('Application link is missing.');
return [{ json: { ...body, candidate: { name: text(candidate.name) || 'Candidate', email }, applicationLink: link, roleTitle: text(body.roleTitle) || 'the published role', expiresAt: text(body.expiresAt) } }];
